 45 |     function changeTreasuryRatio(uint256 _ratio) external {
 46 |         require(msg.sender == engine.governance(), "!gov");
 47 |         treasuryRatio = _ratio;
 48 |     }
 49 | 
 50 |     function changevMochiRatio(uint256 _ratio) external {
 51 |         require(msg.sender == engine.governance(), "!gov");
 52 |         vMochiRatio = _ratio;
 53 |     }
 54 | 
 55 |     // this will open up arb oppertunity for Mochi
 56 |     // so we will not reward the caller, caller can benefit from flashbot
 57 |     // should decide which market we should use UniV2?V3? BalancerV2?
 58 |     function distributeMochi() external {
 59 |         // buy Mochi with mochiShare
 60 |         _buyMochi();
 61 |         _shareMochi();
 62 |     }
 63 | 
 64 |     function _buyMochi() internal {
 65 |         IUSDM usdm = engine.usdm();
 66 |         address[] memory path = new address[](2);
 67 |         path[0] = address(usdm);
 68 |         path[1] = address(engine.mochi());
 69 |         usdm.approve(address(uniswapRouter), mochiShare);
 70 |         uniswapRouter.swapExactTokensForTokens(
 71 |             mochiShare,
 72 |             1,
 73 |             path,
 74 |             address(this),
 75 |             type(uint256).max
 76 |         );
 77 |     }
 78 | 
 79 |     function _shareMochi() internal {
 80 |         IMochi mochi = engine.mochi();
 81 |         uint256 mochiBalance = mochi.balanceOf(address(this));
 82 |         // send Mochi to vMochi Vault
 83 |         mochi.transfer(
 84 |             address(engine.vMochi()),
 85 |             (mochiBalance * vMochiRatio) / 1e18
 86 |         );
 87 |         // send Mochi to veCRV Holders
 88 |         mochi.transfer(
 89 |             crvVoterRewardPool,
 90 |             (mochiBalance * (1e18 - vMochiRatio)) / 1e18
 91 |         );
 92 |         // flush mochiShare
 93 |         mochiShare = 0;
 94 |         treasuryShare = 0;
 95 |     }
 96 | 
 97 |     function sendToTreasury() external {
 98 |         engine.usdm().transfer(engine.treasury(), treasuryShare);
 99 |         treasuryShare = 0;
100 |     }
101 | }
